        @{ Cat = 'DEVELOPER';  Apps = @( @('Microsoft.VisualStudioCode','Visual Studio Code'), @('Git.Git','Git'), @('Python.Python.3.12','Python 3.12'), @('OpenJS.NodeJS.LTS','Node.js LTS') ) }
